import React from 'react';

interface Props {
  name: string;
  age?: number;
}

const Greeting: React.FC<Props> = ({ name, age }) => {
  return (
    <div>
      <h1>Hello, {name}!</h1>
      {age && <p>Age: {age}</p>}
    </div>
  );
};

interface Props {
  name: string;
  age?: number;
}

// Preferred approach - simpler and more explicit
function Greeting({ name, age }: Props) {
  return (
    <div>
      <h1>Hello, {name}!</h1>
      {age && <p>Age: {age}</p>}
    </div>
  );
}

// Arrow function
const Greeting = ({ name, age }: Props) => {
  return <h1>Hello, {name}!</h1>;
};
